const net = require('net_helper')

module.exports = dummy_backend

function dummy_backend(parent_id) {
  const id = parent_id + '/backend'
  const { io, _ } = net(id)

  io.on.app = function (m) {
    const on = {
      'get_btc_balance': on_get_btc_balance,
      'get_ln_balance': on_get_ln_balance,
      'lightning-getinfo': on_getinfo,
      'list_btc_transactions': on_list_btc_txs,
      'get_transaction_history': on_tx_history,
      'get_tx_details_from_btcnode': on_tx_detail,
    }
      ; (on[m.type] || onfail)(m)
    function onfail() { console.warn('[dummy_backend] unknown type:', m.type) }
  }

  function reply(m, data) { // force it to act asynchronously so UI has time to register the wait[head] handler
    setTimeout(() => {
      _.app('response', { cause: m.head }, data)
    }, 0)
  }

  function on_get_btc_balance(m) {
    reply(m, { data: { btc: 0.9600 } })
  }

  function on_get_ln_balance(m) {
    reply(m, { data: { btc: 0.1200 } })
  }

  function on_getinfo(m) {
    reply(m, { data: { alias: 'flamingo-node' } })
  }

  function on_list_btc_txs(m) {
    reply(m, { data: MOCK_BTC_TXS })
  }

  function on_tx_history(m) {
    reply(m, { data: MOCK_LN_TXS })
  }

  function on_tx_detail(m) {
    reply(m, { data: MOCK_TX_DETAIL })
  }

  // Return invite for parent (home_contents) to accept.
  return io.invite('app', { backend: id })
}

